<?php
require_once('../clude/head.php');
include_once('../../inc/connection.php');
$table='kp_front_images';
mysqli_query($connection,"CREATE TABLE IF NOT EXISTS `$table` (image_id INT NOT NULL AUTO_INCREMENT,image_key VARCHAR(60) NOT NULL,label VARCHAR(120) NOT NULL DEFAULT '',description VARCHAR(255) NOT NULL DEFAULT '',file_path VARCHAR(255) NOT NULL DEFAULT '',enabled TINYINT(1) NOT NULL DEFAULT 1,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(image_id),UNIQUE KEY uq_front_image_key(image_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$slots=['front_dashboard'=>['Front Dashboard','Main image or logo displayed on the staff dashboard.'],'kwedia_background'=>['Kwedia Background','Background image for the sales screen.'],'gwitia_background'=>['Gwitia Background','Background image for requisitions and stock requests.'],'kug_background'=>['KUG Background','Background image for the purchase screen.'],'butchery_logo'=>['Butchery Logo','Logo displayed in the butchery header.'],'butchery_background'=>['Butchery Background','Background image for the butchery screen.'],'app_icon'=>['Front App Icon','Small icon used for front-screen branding.']];
foreach($slots as $key=>$meta){$a=mysqli_real_escape_string($connection,$key);$b=mysqli_real_escape_string($connection,$meta[0]);$c=mysqli_real_escape_string($connection,$meta[1]);mysqli_query($connection,"INSERT INTO `$table`(image_key,label,description) VALUES('$a','$b','$c') ON DUPLICATE KEY UPDATE label=VALUES(label),description=VALUES(description)");}
$rows=[];$q=mysqli_query($connection,"SELECT * FROM `$table` ORDER BY image_id");while($q&&($r=mysqli_fetch_assoc($q)))$rows[$r['image_key']]=$r;
?>
<style>
.front-images-card{padding:16px;background:#fff;border:1px solid #e6e9ed;border-radius:10px}.front-images-card h3{margin:0;color:#263238;font-size:19px}.front-images-card .intro{margin:5px 0 15px;color:#71808d;font-size:12px}.front-image-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.front-image-slot{display:grid;grid-template-columns:112px 1fr;gap:12px;align-items:center;padding:11px;border:1px solid #e2e8ed;border-radius:8px;background:#fbfcfd}.front-image-preview{width:112px;height:82px;display:grid;place-items:center;border-radius:7px;background:#edf3f5;color:#8a9aa2;overflow:hidden;font-size:11px;text-align:center}.front-image-preview img{width:100%;height:100%;object-fit:cover}.front-image-slot h4{margin:0 0 4px;font-size:14px;color:#263238}.front-image-slot p{min-height:30px;margin:0 0 8px;color:#75838b;font-size:11px;line-height:1.35}.front-image-slot input[type=file]{width:100%;font-size:11px}.front-image-actions{display:flex;align-items:center;justify-content:space-between;margin-top:7px}.front-image-actions label{font-size:11px}.front-image-actions button{padding:6px 12px;border:0;border-radius:5px;background:#16864c;color:#fff;font-size:11px;font-weight:700}@media(max-width:700px){.front-image-grid{grid-template-columns:1fr}.front-image-slot{grid-template-columns:90px 1fr}.front-image-preview{width:90px;height:70px}}
</style>
<div class="front-images-card"><h3><i class="fa fa-picture-o"></i> Front Images</h3><p class="intro">Upload JPG, PNG, WEBP, or SVG images up to 5 MB. Saving a new image replaces the current image for that slot.</p><div id="front-image-result"></div><div class="front-image-grid">
<?php foreach($slots as $key=>$meta):$row=$rows[$key]??[];$path=trim((string)($row['file_path']??'')); ?>
<form class="front-image-slot front-image-form" enctype="multipart/form-data"><div class="front-image-preview"><?php if($path!==''): ?><img src="../../<?php echo htmlspecialchars($path); ?>?v=<?php echo urlencode((string)($row['updated_at']??'')); ?>" alt="image"><?php else: ?>No image set<?php endif; ?></div><div><h4><?php echo htmlspecialchars($meta[0]); ?></h4><p><?php echo htmlspecialchars($meta[1]); ?></p><input type="hidden" name="image_key" value="<?php echo htmlspecialchars($key); ?>"><input type="file" name="image_file" accept="image/png,image/jpeg,image/webp,image/svg+xml" required><div class="front-image-actions"><label><input type="checkbox" name="enabled" value="1" <?php echo ((int)($row['enabled']??1)===1?'checked':''); ?>> Enabled</label><button type="submit">Save image</button></div></div></form>
<?php endforeach; ?></div></div>
<script>(function(){$('.front-image-form').on('submit',function(e){e.preventDefault();var form=this,btn=$(form).find('button'),data=new FormData(form);data.append('action','save_front_image');btn.prop('disabled',true).text('Saving...');$.ajax({url:'../settings/front_images_act.php',type:'POST',data:data,processData:false,contentType:false,dataType:'html'}).done(function(html){$('#front-image-result').html(html);setTimeout(function(){$('#front-images').trigger('click')},700)}).fail(function(){$('#front-image-result').html('<div class="alert alert-danger">Could not save the image.</div>')}).always(function(){btn.prop('disabled',false).text('Save image')})})})();</script>
